var grayCode = function(n) {
    const result = [];
    const totalCodes = 1 << n;  // 2^n total Gray code values

    for (let i = 0; i < totalCodes; i++) {
        // Formula: Gray code of i = i XOR (i right-shifted by 1)
        const grayValue = i ^ (i >> 1);
        result.push(grayValue);
    }

    return result;
};
